import 'package:flutter/material.dart'; import 'package:provider/provider.dart';
import '../../../core/routing/app_router.dart'; import '../../../core/utils/validators.dart'; import '../../../providers/auth_provider.dart'; import '../../../shared/widgets/app_button.dart'; import '../widgets/auth_form_field.dart';
class LoginScreen extends StatefulWidget { const LoginScreen({super.key}); @override State<LoginScreen> createState()=>_LoginScreenState(); }
class _LoginScreenState extends State<LoginScreen> { final _key=GlobalKey<FormState>(); final _email=TextEditingController(); final _pass=TextEditingController(); @override void dispose(){_email.dispose();_pass.dispose();super.dispose();}
Future<void> _login() async {if(!_key.currentState!.validate())return;final auth=context.read<AuthProvider>();final ok=await auth.login(_email.text,_pass.text);if(!mounted)return;if(ok){Navigator.pushNamedAndRemoveUntil(context,AppRouter.home,(_)=>false);}else{ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(auth.error??'Login failed')));}}
@override Widget build(BuildContext context){final auth=context.watch<AuthProvider>();return Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:440),child:Form(key:_key,child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Icon(Icons.apartment,size:60),Text('Welcome back',textAlign:TextAlign.center,style:Theme.of(context).textTheme.headlineMedium),const SizedBox(height:24),AuthFormField(controller:_email,label:'ALU student email',keyboardType:TextInputType.emailAddress,validator:Validators.aluEmail),const SizedBox(height:14),AuthFormField(controller:_pass,label:'Password',obscureText:true,validator:Validators.password),const SizedBox(height:18),AppButton(label:'Sign in',loading:auth.isLoading,onPressed:_login),TextButton(onPressed:()=>Navigator.pushNamed(context,AppRouter.register),child:const Text('Create an account'))]))))));}}
